package org.marketreview.nativeapp;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;
import static org.marketreview.nativeapp.WatchlistWorkspaceModel.object;

/** New cache databases only. These are genuine Android transactions, never JVM SQLite stubs. */
final class IndustryCompatibilitySqliteChecks {
 interface Work{void run()throws Exception;}
 static void reject(FlowInstrumentation t,Work action,String label)throws Exception{boolean failed=false;try{action.run();}catch(Exception e){failed=true;}t.check(failed,label);}
 static JSONObject docs(String id)throws Exception{return BusinessRestore.payload(new JSONArray().put(object("kind","docs","id",id,"raw",object("id",id,"title","同库专项原件","text","原始中文未改","verification","unverified").toString())));}
 static String asset(FlowInstrumentation t,String name)throws Exception{try(InputStream in=t.getContext().getAssets().open(name)){return new String(MarketFeed.bytes(in,8*1024*1024),StandardCharsets.UTF_8);}}
 static Map<String,String> receipts(File file,String table)throws Exception{
  if(!table.equals(KnownBusinessReceipts.BUSINESS)&&!table.equals(KnownBusinessReceipts.INDUSTRY))throw new IllegalArgumentException("owned tables only");
  Map<String,String> out=new TreeMap<>();try(SQLiteDatabase db=BusinessRestoreSqliteChecks.existing(file)){boolean exists;try(Cursor c=db.rawQuery("SELECT count(*) FROM sqlite_master WHERE type='table' AND name=?",new String[]{table})){if(!c.moveToFirst())throw new IOException("receipt existence missing");exists=c.getInt(0)==1;}if(exists)try(Cursor c=db.rawQuery("SELECT source_key,CAST(payload AS BLOB) FROM "+table+" ORDER BY source_key",null)){while(c.moveToNext())out.put(c.getString(0),Base64.getEncoder().encodeToString(c.getBlob(1)));}}return out;
 }
 static void sql(File file,String text){try(SQLiteDatabase db=BusinessRestoreSqliteChecks.existing(file)){db.execSQL(text);}}
 static JSONObject run(FlowInstrumentation t,File dir,String source)throws Exception{
  int start=t.assertions;JSONObject archive=IndustryArchiveState.payload(source);JSONArray orders=new JSONArray();
  for(String order:new String[]{"business-first","industry-first"}){
   File file=new File(dir,"compat-"+order+".sqlite");BusinessRestoreSqliteChecks.initialize(t,file,new JSONArray());BusinessRestoreStore b=new BusinessRestoreStore(file);IndustryArchiveStore i=new IndustryArchiveStore(file);
   if(order.equals("business-first")){JSONObject p=b.preview(docs("initial-doc"),b.capture());b.commit(p);Map<String,String> before=receipts(file,KnownBusinessReceipts.BUSINESS);t.check(before.size()==1,"actual prior business receipt");JSONObject ip=i.preview(archive,i.capture(Collections.emptyList())),r=i.commit(ip);t.check(i.verify(ip,r,i.capture(Collections.emptyList())),"actual industry after business transaction and independent reread");t.check(before.equals(receipts(file,KnownBusinessReceipts.BUSINESS)),"industry preserves every original business receipt byte");}
   else{JSONObject p=i.preview(archive,i.capture(Collections.emptyList()));i.commit(p);Map<String,String> before=receipts(file,KnownBusinessReceipts.INDUSTRY);t.check(before.size()==1,"actual prior industry receipt");JSONObject bp=b.preview(docs("initial-doc"),b.capture()),r=b.commit(bp);t.check(b.verify(bp,r,b.capture()),"actual business after industry transaction and independent reread");t.check(before.equals(receipts(file,KnownBusinessReceipts.INDUSTRY)),"business preserves every original industry receipt byte");}
   JSONObject beforeB=b.capture(),beforeI=i.capture(Collections.emptyList());t.check(beforeB.getJSONObject("restoreState").has("receiptBytes")&&beforeI.getJSONObject("restoreState").has("receiptBytes"),"both genuine Android snapshots bind known raw receipt bytes");
   String amended=source.replace("保留原配置","后续原配置");JSONObject later=IndustryArchiveState.payload(amended);t.check(!WatchlistWorkspaceModel.equal(later,archive),"distinct immutable later configuration source");JSONObject staleIndustry=i.preview(later,beforeI),staleBusiness=b.preview(docs("second-doc"),beforeB);
   sql(file,"UPDATE business_restore_receipts SET payload='  '||payload||char(10)");JSONObject changedB=b.capture(),changedI=i.capture(Collections.emptyList());t.check(!beforeB.getString("baseline").equals(changedB.getString("baseline"))&&!beforeI.getString("baseline").equals(changedI.getString("baseline")),"business receipt whitespace changes both CAS baselines");t.check(beforeI.getJSONObject("restoreState").getString("recordsHash").equals(changedI.getJSONObject("restoreState").getString("recordsHash")),"whitespace CAS does not rely on records changing");reject(t,()->i.commit(staleIndustry),"foreign business receipt byte CAS rejects industry");reject(t,()->b.commit(staleBusiness),"own business receipt byte CAS rejects business");t.check(BusinessRestore.same(changedB,b.capture()),"stale confirmation leaves all originals unchanged");
   JSONObject pending=i.preview(later,i.capture(Collections.emptyList()));String records=i.capture(Collections.emptyList()).getJSONObject("restoreState").getString("recordsHash");JSONObject empty=b.preview(BusinessRestore.payload(new JSONArray()),b.capture());b.commit(empty);t.check(records.equals(i.capture(Collections.emptyList()).getJSONObject("restoreState").getString("recordsHash")),"actual empty business commit appends only receipt");reject(t,()->i.commit(pending),"actual foreign receipt-only append invalidates pending industry plan");
   JSONObject pb=b.preview(docs("rollback-doc"),b.capture()),pi=i.preview(later,i.capture(Collections.emptyList()));JSONObject stableB=b.capture(),stableI=i.capture(Collections.emptyList());Map<String,String> rawB=receipts(file,KnownBusinessReceipts.BUSINESS),rawI=receipts(file,KnownBusinessReceipts.INDUSTRY);reject(t,()->b.commit(pb,()->{throw new IllegalStateException("controlled rollback");}),"business cancelled transaction rolls back across foreign known table");reject(t,()->i.commit(pi,()->{throw new IllegalStateException("controlled rollback");}),"industry cancelled transaction rolls back across foreign known table");t.check(BusinessRestore.same(stableB,b.capture())&&WatchlistWorkspaceModel.equal(stableI,i.capture(Collections.emptyList()))&&rawB.equals(receipts(file,KnownBusinessReceipts.BUSINESS))&&rawI.equals(receipts(file,KnownBusinessReceipts.INDUSTRY)),"rollback preserves both known raw receipts and every original record");
   try(SQLiteDatabase writer=BusinessRestoreSqliteChecks.existing(file)){writer.beginTransactionNonExclusive();try{writer.execSQL("UPDATE industry_restore_receipts SET payload=' '||payload");t.check(BusinessRestore.same(stableB,b.capture())&&WatchlistWorkspaceModel.equal(stableI,i.capture(Collections.emptyList())),"genuine readonly capture remains coherent while foreign receipt writer is uncommitted");}finally{writer.endTransaction();}}
   JSONObject self=i.preview(later,i.capture(Collections.emptyList())),foreign=b.preview(docs("third-doc"),b.capture());sql(file,"UPDATE industry_restore_receipts SET payload=' '||payload||' '");reject(t,()->i.commit(self),"own industry receipt byte CAS");reject(t,()->b.commit(foreign),"foreign industry receipt byte CAS");orders.put(object("order",order,"passed",true));
  }
  for(String bad:new String[]{"unknown-table","unknown-trigger","wrong-known-ddl","foreign-blob","foreign-seal"}){
   File file=new File(dir,"compat-invalid-"+bad+".sqlite");BusinessRestoreSqliteChecks.initialize(t,file,new JSONArray());BusinessRestoreStore b=new BusinessRestoreStore(file);IndustryArchiveStore i=new IndustryArchiveStore(file);b.commit(b.preview(docs("schema-doc"),b.capture()));i.commit(i.preview(archive,i.capture(Collections.emptyList())));
   switch(bad){case"unknown-table":sql(file,"CREATE TABLE unreviewed(id TEXT)");break;case"unknown-trigger":sql(file,"CREATE TRIGGER unreviewed AFTER INSERT ON records BEGIN SELECT 1; END");break;case"wrong-known-ddl":sql(file,"ALTER TABLE business_restore_receipts ADD COLUMN unreviewed TEXT");break;case"foreign-blob":sql(file,"UPDATE industry_restore_receipts SET payload=CAST(payload AS BLOB)");break;default:sql(file,"UPDATE business_restore_receipts SET payload='{}'");}
   String hash=BusinessRestoreSqliteChecks.fingerprint(file);reject(t,b::capture,"business rejects malformed foreign/unknown "+bad);reject(t,()->i.capture(Collections.emptyList()),"industry rejects malformed foreign/unknown "+bad);t.check(hash.equals(BusinessRestoreSqliteChecks.fingerprint(file)),"rejected malformed foreign source is not repaired or rewritten");
  }
  return object("checks",t.assertions-start,"actualAndroidSqlite",true,"orders",orders,"knownReceiptRawBytesCas",true,"newCacheDatabasesOnly",true,"oldSuitesRerun",false);
 }
}
